// Map TikTok API response → analytics_events rows
const data = $json.data || {};
const videos = data.videos || [];
const rows = [];

for (const video of videos) {
  const contentId = `tiktok:${video.id}`;
  const occurredAt = video.create_time
    ? new Date(parseInt(video.create_time) * 1000).toISOString()
    : new Date().toISOString();

  if (video.view_count !== undefined) {
    rows.push({
      platform: 'tiktok',
      content_id: contentId,
      event_type: 'view',
      occurred_at: occurredAt,
      metric_value: video.view_count,
      metadata: JSON.stringify({ title: video.title })
    });
  }
  if (video.like_count !== undefined) {
    rows.push({
      platform: 'tiktok',
      content_id: contentId,
      event_type: 'like',
      occurred_at: occurredAt,
      metric_value: video.like_count,
      metadata: JSON.stringify({ title: video.title })
    });
  }
  if (video.comment_count !== undefined) {
    rows.push({
      platform: 'tiktok',
      content_id: contentId,
      event_type: 'engagement',
      occurred_at: occurredAt,
      metric_value: video.comment_count,
      metadata: JSON.stringify({ metric: 'comment_count', title: video.title })
    });
  }
  if (video.share_count !== undefined) {
    rows.push({
      platform: 'tiktok',
      content_id: contentId,
      event_type: 'engagement',
      occurred_at: occurredAt,
      metric_value: video.share_count,
      metadata: JSON.stringify({ metric: 'share_count', title: video.title })
    });
  }
}

return rows.map(row => ({ json: row }));
